
import base64
import uuid
import os

# Hardware lock check
MY_PC_ID = "123182154107244"
CURRENT_PC_ID = str(uuid.getnode())

if CURRENT_PC_ID != MY_PC_ID:
    print("ACCESS DENIED. This script is locked to the original owner's PC.")
    exit()

# Decrypt and run
encrypted_b64 = """"""
encrypted_bytes = base64.b64decode(encrypted_b64)
key = MY_PC_ID.encode('utf-8')

decrypted_code = bytearray()
for i in range(len(encrypted_bytes)):
    decrypted_code.append(encrypted_bytes[i] ^ key[i % len(key)])

exec(decrypted_code.decode('utf-8'))
